#include <iostream>
using namespace std;

int main() {
    int h1, b1, h2, b2, tahun;
    cin >> h1 >> b1 >> h2 >> b2 >> tahun;
    int kabisat = 0;
    if (tahun % 400 == 0 || (tahun % 4 == 0 && tahun % 100 != 0)) {
        kabisat = 1;
    }

    int ke1 = h1;
    switch (b1) {
        case 2: ke1 = ke1 + 31; break;
        case 3: ke1 = ke1 + 59; break;
        case 4: ke1 = ke1 + 90; break;
