        case 10: ke1 = ke1 + 273; break;
        case 11: ke1 = ke1 + 304; break;
        case 12: ke1 = ke1 + 334; break;
    }
    if (b1 > 2) {
        ke1 = ke1 + kabisat;
    }

    int ke2 = h2;
    switch (b2) {
        case 2: ke2 = ke2 + 31; break;
        case 3: ke2 = ke2 + 59; break;
